#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.4724658, 0.110452365, 0.067902985], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.02753420000000001, 'zmax': 0.02753420000000001, 'profiles': [{'outer': [[-0.08383403941597001, -0.005870224183912904], [-0.08429392499999999, 3.500000000933312e-08], [-0.087150315, 3.500000000933312e-08], [-0.086056365, 0.013613465000000005], [-0.082774545, 0.020663294999999998], [-0.08153018802999919, 0.020347820197780662], [-0.08016125500000001, 0.026011444999999994], [-0.08283531499999999, 0.026923064999999996], [-0.07760873500000001, 0.039564075000000004], [-0.072321365, 0.045216055000000005], [-0.07123990386829604, 0.04453578314547224], [-0.068188725, 0.04953107500000001], [-0.070498155, 0.05123272500000001], [-0.06162509499999999, 0.061625155000000015], [-0.054818385, 0.065393125], [-0.05398507949800431, 0.06438252473791194], [-0.049531015, 0.068188735], [-0.051171915, 0.070498175], [-0.039564025, 0.07760873500000001], [-0.031967245000000005, 0.079128125], [-0.03146531167529071, 0.07790915038920751], [-0.026011355, 0.080161275], [-0.026922975000000002, 0.082896145], [-0.013613415000000004, 0.08605638500000001], [-0.005955845000000001, 0.08514476500000001], [-0.005849705206912586, 0.08383566194797383], [4.500000000406956e-08, 0.08429393500000001], [4.500000000406956e-08, 0.08715030500000001], [0.013674235, 0.08605638500000001], [0.020663275000000002, 0.082774555], [0.020349752035597673, 0.08153788840907411], [0.026072184999999998, 0.08016124499999999], [0.026923024999999996, 0.08289611499999999], [0.039564085, 0.077608705], [0.045216085, 0.07238212499999999], [0.044537758090456646, 0.07128637319079266], [0.049591825, 0.06818870500000002], [0.051232744999999996, 0.07049814500000001], [0.061625145, 0.061625125], [0.065393135, 0.05481836500000001], [0.06440331908580346, 0.05398763915976725], [0.068188765, 0.049531044999999996], [0.070498175, 0.051232694999999995], [0.077669545, 0.03956404499999999], [0.079128125, 0.031967225000000016], [0.07791870544020192, 0.031469237318021044], [0.080161285, 0.026011384999999998], [0.082896125, 0.026923005], [0.086117155, 0.013613405000000009], [0.085144755, 0.005955874999999999], [0.08383436644391519, 0.005866125474663206], [0.08429392499999999, -2.500000000071889e-08], [0.087150315, -2.500000000071889e-08], [0.086117145, -0.013613454999999997], [0.082835335, -0.020663285000000003], [0.08154034514543511, -0.02033953457689607], [0.080161265, -0.026072175000000003], [0.08289611499999999, -0.026923025000000003], [0.077669515, -0.039564064999999995], [0.072382155, -0.045216074999999994], [0.07127632680180869, -0.04452047334412513], [0.068188735, -0.049531034999999994], [0.070498135, -0.051232725], [0.061625105, -0.061625135], [0.054879145, -0.06539313499999999], [0.054045855575983334, -0.06438254778140831], [0.049591785, -0.06818875499999999], [0.051232705, -0.070498165], [0.039564035, -0.07766952499999999], [0.031967255, -0.079128115], [0.031489286535635846, -0.07792433588247963], [0.026072134999999996, -0.080161265], [0.026922975000000002, -0.082896105], [0.013674184999999998, -0.086056365], [0.005955854999999996, -0.085144765], [0.005867311394869019, -0.08383426952394014], [-1.500000000598245e-08, -0.08429392499999999], [-1.500000000598245e-08, -0.087150305], [-0.013613465000000005, -0.08605634499999999], [-0.020602495, -0.082835325], [-0.020297225872553323, -0.08154241055324699], [-0.026011405, -0.080161255], [-0.026923025000000003, -0.082896095], [-0.039564075000000004, -0.077669515], [-0.045216085, -0.072382145], [-0.04451294442775979, -0.07126433657475208], [-0.049531055000000004, -0.068188725], [-0.051171955000000005, -0.07049813499999999], [-0.061625135, -0.061625084999999996], [-0.065332365, -0.054879155], [-0.06434083669710004, -0.05402926985172824], [-0.06818875499999999, -0.049531004999999996], [-0.07049818499999999, -0.051232694999999995], [-0.077608765, -0.039564035], [-0.079128115, -0.03196724499999999], [-0.07789868997979285, -0.03148617482201783], [-0.080161275, -0.026072114999999993], [-0.08283532499999999, -0.026922964999999993], [-0.08605637499999999, -0.013613395], [-0.085083985, -0.005955845000000001]], 'holes': [[[-0.021928005, 0.02436063499999999], [-0.018122764039166236, 0.026843311591708878], [-0.021939495000000003, 0.024370494999999992], [-0.024324241578731344, 0.021423303929842437]]]}], 'simplify_tolerance': 3.4860126000000006e-05, 'sketch_entity_count': 108}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
